def is_prime(n: int) -> bool:
    """Return True when *n* is a prime number. Numbers below 2 are not prime.
    """
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    limit = math.isqrt(n)
    for d in range(3, limit + 1, 2):
        if n % d == 0:
            return False
    return True

